const lockProjectsForOrigins = `-- name: LockProjectsForOrigins :many
SELECT id FROM projects WHERE id=ANY($1::uuid[]) ORDER BY id FOR KEY SHARE
`

func (q *Queries) LockProjectsForOrigins(ctx context.Context, dollar_1 []ids.ID) ([]ids.ID, error) {
	rows, err := q.db.QueryContext(ctx, lockProjectsForOrigins, pq.Array(dollar_1))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ids.ID
	for rows.Next() {
		var id ids.ID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

