const reviewSummariesPage = `-- name: ReviewSummariesPage :many

WITH page AS (
  SELECT id FROM conformance_reviews ORDER BY id DESC LIMIT NULLIF($1::bigint, 0)
), needed AS (
  SELECT id FROM page
  UNION (SELECT r.id FROM conformance_reviews r WHERE r.status = $2 AND r.id < (SELECT page.id FROM page ORDER BY page.id LIMIT 1) ORDER BY r.id DESC LIMIT 1)
)
SELECT id, number, trigger, actor, actor_principal, actor_via, started_at, finished_at, projects, verdicts, errors, cost, status, projects_total, projects_done, current_project, selected_projects, build, build_budget FROM conformance_reviews WHERE id IN (SELECT id FROM needed) ORDER BY id DESC
`

type ReviewSummariesPageParams struct {
	Column1 int64
	Status  string
}

// The page a person sees, plus the newest finished review before it so a
// comparison always has something to compare against. A zero limit is every
// review: NULLIF turns it into LIMIT NULL, which is what "no bound" was.
func (q *Queries) ReviewSummariesPage(ctx context.Context, arg ReviewSummariesPageParams) ([]ConformanceReview, error) {
	rows, err := q.db.QueryContext(ctx, reviewSummariesPage, arg.Column1, arg.Status)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ConformanceReview
	for rows.Next() {
		var i ConformanceReview
		if err := rows.Scan(
			&i.ID,
			&i.Number,
			&i.Trigger,
			&i.Actor,
			&i.ActorPrincipal,
			&i.ActorVia,
			&i.StartedAt,
			&i.FinishedAt,
			&i.Projects,
			&i.Verdicts,
			&i.Errors,
			&i.Cost,
			&i.Status,
			&i.ProjectsTotal,
			&i.ProjectsDone,
			&i.CurrentProject,
			&i.SelectedProjects,
			&i.Build,
			&i.BuildBudget,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

